}

func (command StepCommand) validate() error {
	if command.Schema != StepSchema || !unitRE.MatchString(command.Cell) || !entityid.Valid(command.RolloutID) ||
		command.Kind != rollout.KindController && command.Kind != rollout.KindHost || !unitRE.MatchString(command.Unit) ||
		!entityid.Valid(command.OperationID) || command.Action != StepPrepare && command.Action != StepRollback ||
		!digestRE.MatchString(command.Digest) || command.Epoch == 0 || command.ProofWindowSeconds <= 0 ||
		len(command.Receipt) > maxReleaseWire || len(command.Delegation) > maxReleaseWire ||
		len(command.Delegation) > 0 && len(command.Receipt) == 0 ||
		!digestRE.MatchString(command.Replaces) || command.Replaces == command.Digest {
		return fmt.Errorf("%w: step command", ErrInvalid)
	}
	return nil
}

// stepScope binds the signature to one operation, action and unit.
func stepScope(command StepCommand) trust.Scope {
	return trust.Scope{Domain: StepDomain, DeploymentID: command.OperationID, Cell: command.Cell,
		Environment: stepEnvironment, Role: string(command.Action), Slot: command.Unit}
}

// SignStepCommand signs command with the leader's controller key. The
// signature expires at deadline, or StepLifetime after now when that is
// sooner or deadline is zero: an agent never acts on a step after the phase
// deadline the leader enforces for it.
func SignStepCommand(command StepCommand, key ed25519.PrivateKey, now, deadline time.Time) ([]byte, error) {
	if err := command.validate(); err != nil {
		return nil, err
	}
	expires := now.Add(StepLifetime)
	if !deadline.IsZero() && deadline.Before(expires) {
		expires = deadline
	}
	if !expires.After(now) {
		return nil, fmt.Errorf("%w: step deadline has passed", ErrInvalid)
	}
	payload, err := trust.EncodePayload(command)
	if err != nil {
		return nil, err
	}
	envelope, err := trust.Sign(payload, stepScope(command), now, expires, key)
	if err != nil {
		return nil, err
	}
	return trust.EncodeEnvelope(envelope)
}

// VerifyStepCommand accepts a current command for exactly this cell and
// unit, signed by one of the controller keys. It also returns when the
// signature expires: the agent must not act on the command after that.
func VerifyStepCommand(wire []byte, cell, unit string, keys trust.Keyring, now time.Time) (StepCommand, time.Time, error) {
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return StepCommand{}, time.Time{}, err
	}
	scope := envelope.Scope
	if scope.Domain != StepDomain || scope.Cell != cell || scope.Slot != unit || scope.Environment != stepEnvironment ||
		scope.Role != string(StepPrepare) && scope.Role != string(StepRollback) {
		return StepCommand{}, time.Time{}, trust.ErrScopeMismatch
	}
	payload, err := trust.VerifyCurrent(envelope, scope, keys, now, trust.Policy{MaxLifetime: StepLifetime, ClockSkew: stepClockSkew})
	if err != nil {
		return StepCommand{}, time.Time{}, err
	}
	var command StepCommand
	if err := protocol.DecodeStrict(payload, &command, trust.MaxPayloadBytes); err != nil {
		return StepCommand{}, time.Time{}, err
	}
	if err := command.validate(); err != nil {
		return StepCommand{}, time.Time{}, err
	}
	if stepScope(command) != scope {
		return StepCommand{}, time.Time{}, trust.ErrScopeMismatch
	}
	return command, envelope.ExpiresAt, nil
}

func (d KVDriver) Step(ctx context.Context, step Step) (StepReply, error) {
	if d.KV == nil || len(d.Key) != ed25519.PrivateKeySize {
		return StepReply{}, fmt.Errorf("%w: step driver configuration", ErrInvalid)
	}
	now := time.Now
	if d.Now != nil {
		now = d.Now
	}
	timeout := d.Timeout
	if timeout <= 0 {
		timeout = 30 * time.Second
	}
	// The receipt lookup, signing and the writes share one deadline.
	requestCtx, cancel := context.WithTimeout(ctx, timeout)
	defer cancel()
	command := StepCommand{Schema: StepSchema, Cell: d.Cell, RolloutID: step.RolloutID, Kind: step.Kind, Unit: step.Unit,
		OperationID: step.OperationID, Action: step.Action, Digest: step.Digest, Replaces: step.Replaces, Epoch: step.Epoch,
		ProofWindowSeconds: int64(step.ProofWindow / time.Second)}
	if d.Releases != nil {
		receipt, delegation, err := d.Releases.Receipt(requestCtx, step.Digest)
		if err != nil {
			return StepReply{}, fmt.Errorf("read release receipt: %w", err)
		}
		command.Receipt, command.Delegation = receipt, delegation
	}
	wire, err := SignStepCommand(command, d.Key, now().UTC(), step.Deadline)
	if err != nil {
		return StepReply{}, err
	}
	// The lease is re-checked after the lookup and signing, immediately
	// before the step leaves: a leader that lost it meanwhile sends nothing.
	if step.Fence != nil {
		if err := step.Fence(requestCtx); err != nil {
			return StepReply{}, err
		}
	}
	if _, err := d.KV.Put(requestCtx, StepKey(step.Unit), wire); err != nil {
		return StepReply{}, fmt.Errorf("post rollout step: %w", err)
	}
	waiting := StepReply{OperationID: step.OperationID, Unit: step.Unit, Outcome: OutcomeRetry,
		Reason: "waiting for the unit's step agent"}
	entry, err := d.KV.Get(requestCtx, ReplyKey(step.Unit))
	if errors.Is(err, jetstream.ErrKeyNotFound) {
		return waiting, nil
	}
	if err != nil {
		return StepReply{}, fmt.Errorf("read rollout step reply: %w", err)
	}
	// A reply to an earlier step of the unit is not an answer to this one.
	if reply, err := decodeReply(entry.Value(), step); err == nil {
		return reply, nil
	}
	return waiting, nil
}

func decodeReply(data []byte, step Step) (StepReply, error) {
	if len(data) > maxReplyBytes {
		return StepReply{}, fmt.Errorf("%w: step reply too large", ErrInvalid)
	}
	var reply StepReply
	if err := json.Unmarshal(data, &reply); err != nil {
		return StepReply{}, fmt.Errorf("decode step reply: %w", err)
	}
	switch reply.Outcome {
	case OutcomeActivated, OutcomePending, OutcomeCurrent, OutcomeRetry, OutcomeRefused:
	default:
		return StepReply{}, fmt.Errorf("%w: step reply outcome", ErrInvalid)
	}
	if reply.OperationID != step.OperationID || reply.Unit != step.Unit || reply.Epoch != step.Epoch ||
		len(reply.Reason) > maxReplyReason {
		return StepReply{}, errors.New("step reply does not answer this step")
	}
	return reply, nil
}

func (r *Relay) Pass(ctx context.Context) error {
	entry, err := r.KV.Get(ctx, StepKey(r.Unit))
	switch {
	case errors.Is(err, jetstream.ErrKeyNotFound):
		err = nil // no step for this unit: the usual state between rollouts
	case err != nil:
		return err
	default:
		err = r.Spool(ctx, entry.Value())
	}
	return errors.Join(err, r.relayReply(ctx))
}

// Spool hands a current step to the agent, after the binary it names, so
// the agent rarely sees a step whose release is still downloading. A failed
// download still spools the step: the agent's retry reply tells the leader
// why nothing moves.
func (r *Relay) Spool(ctx context.Context, wire []byte) error {
	command, _, err := VerifyStepCommand(wire, r.Cell, r.Unit, r.Leaders, r.now())
	if err != nil {
		// Expired, or not this unit's: the leader posts a fresh one.
		return nil
	}
	path := filepath.Join(r.Dir, spoolStep)
	if current, err := os.ReadFile(path); err == nil && bytes.Equal(current, wire) {
		return nil
	}
	fetchErr := r.fetch(ctx, command.Digest)
	return errors.Join(fetchErr, writeFileAtomic(path, wire, 0o600))
}

// fetch spools the binary of digest unless the node already staged it, and
// removes every other spooled binary.
func (r *Relay) fetch(ctx context.Context, digest string) error {
	entries, err := os.ReadDir(r.Dir)
	if err != nil {
		return err
	}
	name := spoolReleasePrefix + digest
	for _, entry := range entries {
		if entry.Name() != name && (strings.HasPrefix(entry.Name(), spoolReleasePrefix) || strings.HasPrefix(entry.Name(), ".")) {
			_ = os.Remove(filepath.Join(r.Dir, entry.Name()))
		}
	}
	if _, err := os.Stat(r.Layout.BinaryPath(digest)); err == nil {
		return nil
	}
	if _, err := os.Stat(filepath.Join(r.Dir, name)); err == nil || len(r.Sources) == 0 {
		return nil
	}
	var failures []error
	for _, source := range r.Sources {
		err := writeVerified(ctx, filepath.Join(r.Dir, name), digest, source)
		if err == nil {
			return nil
		}
		failures = append(failures, err)
	}
	return fmt.Errorf("fetch release %s: %w", short(digest), errors.Join(failures...))
}

// Reply returns the agent's newest reply for the unit, nil when it has
// none.
func (r *Relay) Reply() ([]byte, error) {
	data, err := os.ReadFile(filepath.Join(r.Layout.Root, ReplyFile(r.SystemdUnit)))
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var reply StepReply
	if len(data) > maxReplyBytes || json.Unmarshal(data, &reply) != nil || reply.Unit != r.Unit {
		return nil, fmt.Errorf("%w: rollout step reply", ErrInvalid)
	}
	return data, nil
}

// relayReply posts the agent's newest reply to the unit's reply key.
func (r *Relay) relayReply(ctx context.Context) error {
	data, err := r.Reply()
	if err != nil || data == nil || bytes.Equal(data, r.relayed) {
		return err
	}
	if _, err := r.KV.Put(ctx, ReplyKey(r.Unit), data); err != nil {
		return err
	}
	r.relayed = data
	return nil
}

func (r *Relay) now() time.Time {
	if r.Now != nil {
		return r.Now().UTC()
	}
	return time.Now().UTC()
}

// writeVerified writes the binary of digest from source to path, keeping it
// only when its bytes hash to digest.
func writeVerified(ctx context.Context, path, digest string, source BinarySource) error {
	file, err := os.CreateTemp(filepath.Dir(path), ".download-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	hash := sha256.New()
	if err := source(ctx, digest, &limitWriter{w: io.MultiWriter(file, hash), left: selfupdate.MaxBinaryBytes}); err != nil {
		return err
	}
	if hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: fetched bytes differ from release %s", ErrInvalid, short(digest))
	}
	if err := file.Close(); err != nil {
		return err
	}
	return os.Rename(file.Name(), path)
}

func (l *limitWriter) Write(p []byte) (int, error) {
	if int64(len(p)) > l.left {
		return 0, fmt.Errorf("%w: release exceeds %d bytes", ErrInvalid, selfupdate.MaxBinaryBytes)
	}
	l.left -= int64(len(p))
	return l.w.Write(p)
}

func ApplySpooled(ctx context.Context, agent *Agent, dir string, verifier selfupdate.Verifier) error {
	spool, err := os.OpenRoot(dir)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	defer spool.Close()
	wire, err := readSpooled(spool, spoolStep, trust.MaxEnvelopeBytes)
	if errors.Is(err, fs.ErrNotExist) {
		return nil
	}
	if err != nil {
		return err
	}
	command, expires, err := VerifyStepCommand(wire, agent.Cell, agent.Unit, agent.Leaders, agent.now())
	if err != nil {
		return nil
	}
	if verifier != nil {
		agent.Fetch = spoolFetcher{spool: spool, verifier: verifier, now: agent.now}
	}
	data, err := json.Marshal(agent.handle(ctx, command, expires))
	if err != nil {
		return err
	}
	return writeFileAtomic(filepath.Join(agent.Layout.Root, ReplyFile(agent.SystemdUnit)), data, 0o644)
}

// spoolFetcher stages a release from the binary the relay spooled. Stage
// verifies the receipt, the exact size and the digest before it keeps a
// byte.
type spoolFetcher struct {
	spool    *os.Root
	verifier selfupdate.Verifier
	now      func() time.Time
}

func (f spoolFetcher) Fetch(_ context.Context, layout selfupdate.Layout, receipt, delegation []byte) (string, error) {
	verified, err := f.verifier.Verify(receipt, delegation, f.now())
	if err != nil {
		return "", fmt.Errorf("verify release receipt: %w", err)
	}
	file, err := openSpooled(f.spool, spoolReleasePrefix+verified.Receipt().SHA256)
	if err != nil {
		return "", err
	}
	defer file.Close()
	unlock, err := layout.Lock()
	if err != nil {
		return "", err
	}
	defer unlock()
	return selfupdate.Stage(layout, file, receipt, delegation, f.verifier, f.now())
}

// openSpooled opens a regular file beneath the spool. O_NONBLOCK keeps a
// FIFO the controller put there from blocking the root agent.
func openSpooled(spool *os.Root, name string) (*os.File, error) {
	file, err := spool.OpenFile(name, os.O_RDONLY|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, err
	}
	if info, err := file.Stat(); err != nil || !info.Mode().IsRegular() {
		file.Close()
		return nil, fmt.Errorf("%w: spooled %s is not a regular file", ErrInvalid, name)
	}
	return file, nil
}

func readSpooled(spool *os.Root, name string, limit int64) ([]byte, error) {
	file, err := openSpooled(spool, name)
	if err != nil {
		return nil, err
	}
	defer file.Close()
	data, err := io.ReadAll(io.LimitReader(file, limit+1))
	if err == nil && int64(len(data)) > limit {
		err = fmt.Errorf("%w: spooled %s is too large", ErrInvalid, name)
	}
	return data, err
}

// writeFileAtomic replaces path with data through a temporary file in the
// same directory.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	file, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+"-")
	if err != nil {
		return err
	}
	defer os.Remove(file.Name())
	defer file.Close()
	if err := file.Chmod(mode); err != nil {
		return err
	}
	if _, err := file.Write(data); err != nil {
		return err
	}
	if err := file.Sync(); err != nil {
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	return os.Rename(file.Name(), path)
}

func (a *Agent) now() time.Time {
	if a.Now != nil {
		return a.Now().UTC()
	}
	return time.Now().UTC()
}

// Handle verifies and applies one step and returns the reply.
func (a *Agent) Handle(ctx context.Context, wire []byte) StepReply {
	command, expires, err := VerifyStepCommand(wire, a.Cell, a.Unit, a.Leaders, a.now())
	if err != nil {
		return StepReply{Unit: a.Unit, Outcome: OutcomeRefused, Reason: "step command did not verify"}
	}
	return a.handle(ctx, command, expires)
}

// handle applies one verified command that expires at expires.
func (a *Agent) handle(ctx context.Context, command StepCommand, expires time.Time) StepReply {
	reply := StepReply{OperationID: command.OperationID, Unit: a.Unit, Epoch: command.Epoch}
	a.mu.Lock()
	defer a.mu.Unlock()
	window := max(selfupdate.MinProofWindow, min(selfupdate.MaxProofWindow,
		time.Duration(command.ProofWindowSeconds)*time.Second))
	// Nothing, staging included, outlives the signed command.
	stepCtx, cancel := context.WithDeadline(ctx, expires)
	defer cancel()
	reply.Outcome, reply.Reason = a.apply(stepCtx, command, expires, window)
	return reply
}

// apply fences the step by its authority epoch, which the release root
// records durably: an older leader's step is refused even after this agent
// restarted. The restart obligation is recorded before the release changes
// and cleared only by the unit's next start, so any interruption leaves the
// watchdog (and a retry by a new agent) a restart to finish.
func (a *Agent) apply(ctx context.Context, command StepCommand, expires time.Time, window time.Duration) (StepOutcome, string) {
	if outcome, reason := a.locked(func() (StepOutcome, string) {
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		return a.admit(command)
	}); outcome != "" {
		return outcome, reason
	}
	if outcome, reason := a.ensureStaged(ctx, command); outcome != "" {
		return outcome, reason
	}
	outcome, reason := a.locked(func() (StepOutcome, string) {
		// Re-checked under the lock, immediately before the selection
		// changes: waiting for the lock or a staging download must not
		// let an expired command act.
		if !a.now().Before(expires) {
			return OutcomeRetry, "step command expired before it could be applied"
		}
		if a.Guard != nil {
			if err := a.Guard(ctx, command); err != nil {
				return OutcomeRefused, err.Error()
			}
		}
		if outcome, reason := a.admit(command); outcome != "" {
			return outcome, reason
		}
		if command.Action == StepRollback {
			return a.restore(command)
		}
		return a.activate(command, window)
	})
	if !outcome.Accepted() {
		return outcome, reason
	}
	owed, err := a.owed()
	if err != nil {
		return OutcomeRetry, "restart obligation is unreadable"
	}
	if !owed || a.served == command.OperationID && outcome != OutcomeActivated {
		return outcome, reason
	}
	if err := a.restart(ctx); err != nil {
		slog.WarnContext(ctx, "rollout agent could not restart its unit", "component", "rollout", "unit", a.Unit, "error", err)
		return OutcomeRetry, "unit restart failed"
	}
	a.served = command.OperationID
	return outcome, reason
}

// admit records the step's epoch, refusing an older one. The caller holds
// Layout.Lock.
func (a *Agent) admit(command StepCommand) (StepOutcome, string) {
	if err := a.Layout.AdmitEpoch(command.Epoch); errors.Is(err, selfupdate.ErrStaleEpoch) {
		return OutcomeRefused, "step is from an older authority epoch"
	} else if err != nil {
		return OutcomeRetry, "authority epoch record is unreadable"
	}
	return "", ""
}

func (a *Agent) owed() (bool, error) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return false, err
	}
	defer unlock()
	return a.Layout.RestartPending(a.SystemdUnit)
}

// locked runs step under Layout.Lock.
func (a *Agent) locked(step func() (StepOutcome, string)) (StepOutcome, string) {
	unlock, err := a.Layout.Lock()
	if err != nil {
		return OutcomeRetry, "release root is locked"
	}
	defer unlock()
	return step()
}

// ensureStaged restages a release that is not in the release root (a
// rollback target pruned after its activation settled) from the step's
// signed receipt. It runs unlocked, like selfupdate's own fetch.
func (a *Agent) ensureStaged(ctx context.Context, command StepCommand) (StepOutcome, string) {
	err := a.Layout.VerifyRelease(command.Digest)
	switch {
	case err == nil:
		return "", ""
	case !errors.Is(err, fs.ErrNotExist):
		return OutcomeRefused, "staged release does not verify"
	case a.Fetch == nil || len(command.Receipt) == 0:
		return OutcomeRefused, "release is not staged and cannot be restaged"
	}
	staged, err := a.Fetch.Fetch(ctx, a.Layout, command.Receipt, command.Delegation)
	if err != nil {
		slog.WarnContext(ctx, "rollout agent could not stage a release", "component", "rollout", "unit", a.Unit,
			"digest", command.Digest, "error", err)
		return OutcomeRetry, "release staging failed"
	}
	if staged != command.Digest {
		return OutcomeRefused, "the step's receipt names another release"
	}
	return "", ""
}

// activate moves the unit forward through a proof-gated A/B activation.
// A retry of a matching pending activation goes through Activate again, so
// its gates rerun and an interrupted link flip is repaired. The caller
// holds Layout.Lock.
func (a *Agent) activate(command StepCommand, window time.Duration) (StepOutcome, string) {
	digest := command.Digest
	pending, exists, err := a.Layout.Pending()
	if err != nil {
		return OutcomeRetry, "activation state is unreadable"
	}
	if exists && (pending.Target != digest || pending.Unit != a.SystemdUnit || pending.Previous != command.Replaces) {
		// The watchdog resolves the other activation by its deadline.
		return OutcomeRetry, "another activation is pending"
	}
	if !exists {
		if current, err := a.Layout.Current(); err != nil {
			return OutcomeRetry, "current release is unreadable"
		} else if current == digest {
			return OutcomeCurrent, ""
		} else if current != command.Replaces {
			// A forward step only moves the unit off the rollout's
			// predecessor: a replayed step of an earlier rollout never
			// undoes the update that settled after it.
			return OutcomeRefused, "the unit does not run the step's predecessor release"
		}
		// Owed before the link moves, so an interruption after it never
		// leaves the old process running until the watchdog rejects a
		// release that never started.
		if err := a.Layout.MarkRestartPending(a.SystemdUnit); err != nil {
			return OutcomeRetry, "restart obligation could not be recorded"
		}
	}
	if _, err := selfupdate.Activate(a.Layout, digest, a.SystemdUnit, a.now(), window); err != nil {
		if !exists {
			// Nothing to restart unless the activation record was written;
			// an unreadable activation state keeps the obligation.
			if _, recorded, pendingErr := a.Layout.Pending(); pendingErr == nil && !recorded {
				_ = a.Layout.ClearRestartPending(a.SystemdUnit)
			}
		}
		if errors.Is(err, selfupdate.ErrKnownBad) {
			return OutcomeRefused, "release is known bad on this node"
		}
		slog.Warn("rollout agent could not activate a release", "component", "rollout", "unit", a.Unit,
			"digest", digest, "error", err)
		return OutcomeRetry, "activation failed"
	}
	if exists {
		return OutcomePending, ""
	}
	return OutcomeActivated, ""
}

// restore returns the unit to the rollout's predecessor without a pending
// activation (selfupdate.Restore), so the watchdog can never flip it back
// to the rejected release. The caller holds Layout.Lock.
func (a *Agent) restore(command StepCommand) (StepOutcome, string) {
	if pending, exists, err := a.Layout.Pending(); err != nil {
		return OutcomeRetry, "activation state is unreadable"
	} else if exists && (pending.Unit != a.SystemdUnit || pending.Target != command.Replaces || pending.Previous != command.Digest) {
		return OutcomeRetry, "another activation is pending"
	}
	changed, err := selfupdate.Restore(a.Layout, command.Digest, command.Replaces, a.SystemdUnit)
	switch {
	case errors.Is(err, selfupdate.ErrKnownBad):
		return OutcomeRefused, "release is known bad on this node"
	case errors.Is(err, selfupdate.ErrInvalid):
		return OutcomeRefused, "the unit runs neither release of the rollout"
	case err != nil:
		slog.Warn("rollout agent could not restore a release", "component", "rollout", "unit", a.Unit,
			"digest", command.Digest, "error", err)
		return OutcomeRetry, "restore failed"
	case !changed:
		return OutcomeCurrent, ""
	}
	return OutcomeActivated, ""
}

func (a *Agent) restart(ctx context.Context) error {
	if a.Restart == nil {
		return errors.New("no restarter")
	}
	return a.Restart(ctx, a.SystemdUnit)
}

func (policy ReceiptPolicy) Verify(receiptWire, delegationWire []byte, now time.Time) (release.VerifiedBinary, error) {
	if len(policy.Roots) == 0 {
		return release.VerifiedBinary{}, fmt.Errorf("%w: no release trust roots", ErrInvalid)
	}
	envelope, err := trust.DecodeEnvelope(receiptWire)
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	var verified release.VerifiedBinary
	switch envelope.Scope.Domain {
	case release.BinaryDomain:
		return release.VerifiedBinary{}, fmt.Errorf("%w: self-update requires a region-qualified update receipt", release.ErrProductionQualification)
	case release.UpdateReceiptDomain:
		verified, err = release.VerifyQualifiedBinaryUpdateCurrent(receiptWire, delegationWire, policy.Roots,
			release.UpdateExpectation{Environment: policy.Environment, Cell: policy.Cell, Architecture: policy.Architecture}, now)
	default:
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt domain %q", ErrInvalid, envelope.Scope.Domain)
	}
	if err != nil {
		return release.VerifiedBinary{}, err
	}
	if !verified.IsVerified() || verified.Receipt().GOARCH != policy.Architecture {
		return release.VerifiedBinary{}, fmt.Errorf("%w: receipt architecture differs from this node", release.ErrExpectationMismatch)
	}
	return verified, nil
}

// Verifier is the receipt check Stage applies before any byte is kept.
type Verifier interface {
	Verify(receiptWire, delegationWire []byte, now time.Time) (release.VerifiedBinary, error)
}

// Stage verifies the receipt, copies the binary from source while hashing
// it, requires the exact signed size and digest, and installs it read-only
// under releases/<sha256>. It is idempotent for an already staged release.
// The caller holds Layout.Lock.
func Stage(layout Layout, source io.Reader, receiptWire, delegationWire []byte, verifier Verifier, now time.Time) (string, error) {
	if source == nil || verifier == nil {
		return "", fmt.Errorf("%w: stage source and verifier are required", ErrInvalid)
	}
	verified, err := verifier.Verify(receiptWire, delegationWire, now)
	if err != nil {
		return "", fmt.Errorf("verify release receipt: %w", err)
	}
	receipt := verified.Receipt()
	if knownBad, err := layout.KnownBad(); err != nil {
		return "", err
	} else if knownBad[receipt.SHA256] {
		return "", ErrKnownBad
	}
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(receipt.SHA256)); err == nil {
		if err := layout.VerifyRelease(receipt.SHA256); err != nil {
			return "", err
		}
		return receipt.SHA256, nil
	}
	if err := layout.install(source, receipt.SHA256, receipt.Bytes, map[string][]byte{
		receiptFile: receiptWire, delegationFile: delegationWire,
	}); err != nil {
		return "", err
	}
	return receipt.SHA256, nil
}

func Seed(layout Layout, bakedBinary string) (string, error) {
	if err := layout.ensureDirs(); err != nil {
		return "", err
	}
	current, err := layout.Current()
	if err != nil || current != "" {
		return current, err
	}
	file, err := os.Open(bakedBinary)
	if err != nil {
		return "", err
	}
	defer file.Close()
	info, err := file.Stat()
	if err != nil || !info.Mode().IsRegular() || info.Size() <= 0 || info.Size() > MaxBinaryBytes {
		return "", fmt.Errorf("%w: baked binary", ErrInvalid)
	}
	digest, _, err := hashFile(bakedBinary)
	if err != nil {
		return "", err
	}
	if _, err := os.Lstat(layout.ReleaseDir(digest)); errors.Is(err, os.ErrNotExist) {
		if err := layout.install(file, digest, info.Size(), map[string][]byte{bakedMarkerFile: []byte(bakedBinary + "\n")}); err != nil {
			return "", err
		}
	}
	if err := layout.VerifyRelease(digest); err != nil {
		return "", err
	}
	return digest, layout.flipCurrent(digest)
}

func (layout Layout) install(source io.Reader, digest string, size int64, metadata map[string][]byte) error {
	if !digestRE.MatchString(digest) || size <= 0 || size > MaxBinaryBytes {
		return fmt.Errorf("%w: release identity", ErrInvalid)
	}
	temporary, err := os.MkdirTemp(layout.releasesPath(), ".staging-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(temporary)
	if err := os.Chmod(temporary, 0o755); err != nil {
		return err
	}
	binary, err := os.OpenFile(filepath.Join(temporary, BinaryName), os.O_CREATE|os.O_EXCL|os.O_WRONLY, 0o500)
	if err != nil {
		return err
	}
	hash := sha256.New()
	written, copyErr := io.Copy(io.MultiWriter(binary, hash), io.LimitReader(source, size+1))
	if copyErr == nil {
		copyErr = binary.Chmod(0o555)
	}
	if copyErr == nil {
		copyErr = binary.Sync()
	}
	if closeErr := binary.Close(); copyErr == nil {
		copyErr = closeErr
	}
	if copyErr != nil {
		return copyErr
	}
	if written != size || hex.EncodeToString(hash.Sum(nil)) != digest {
		return fmt.Errorf("%w: staged binary differs from its signed size or digest", ErrInvalid)
	}
	for name, data := range metadata {
		if err := writeSyncedFile(filepath.Join(temporary, name), data, 0o444); err != nil {
			return err
		}
	}
	if err := syncDir(temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, layout.ReleaseDir(digest)); err != nil {
		return err
	}
	if err := syncDir(layout.releasesPath()); err != nil {
		return err
	}
	return layout.VerifyRelease(digest)
}

// writeSyncedFile creates path with data and syncs it before the caller
// syncs and renames the directory, so a crash never keeps a release whose
// metadata files are empty or truncated.
func writeSyncedFile(path string, data []byte, mode os.FileMode) error {
	file, err := os.OpenFile(path, os.O_CREATE|os.O_EXCL|os.O_WRONLY, mode)
	if err != nil {
		return err
	}
	_, err = file.Write(data)
	if err == nil {
		err = file.Chmod(mode)
	}
	if err == nil {
		err = file.Sync()
	}
	if closeErr := file.Close(); err == nil {
		err = closeErr
	}
	return err
}

func NewLayout(root string) Layout { return Layout{Root: root, Owner: 0} }

func (layout Layout) validate() error {
	if !filepath.IsAbs(layout.Root) || filepath.Clean(layout.Root) != layout.Root || layout.Owner < 0 {
		return fmt.Errorf("%w: release root must be a clean absolute path", ErrInvalid)
	}
	return nil
}

func (layout Layout) releasesPath() string { return filepath.Join(layout.Root, releasesDir) }
func (layout Layout) currentPath() string  { return filepath.Join(layout.Root, currentLink) }
func (layout Layout) activationPath() string {
	return filepath.Join(layout.Root, activationFile)
}
func (layout Layout) knownBadPath() string { return filepath.Join(layout.Root, knownBadFile) }

// ReleaseDir is the directory of one staged release.
func (layout Layout) ReleaseDir(digest string) string {
	return filepath.Join(layout.releasesPath(), digest)
}

// BinaryPath is the executable of one staged release.
func (layout Layout) BinaryPath(digest string) string {
	return filepath.Join(layout.ReleaseDir(digest), BinaryName)
}

// CurrentExecutable is the path the systemd ExecStart line runs.
func (layout Layout) CurrentExecutable() string {
	return filepath.Join(layout.currentPath(), BinaryName)
}

// ensureDirs creates the root and releases directories with exclusive
// ownership and verifies existing ones.
func (layout Layout) ensureDirs() error {
	if err := layout.validate(); err != nil {
		return err
	}
	for _, path := range []string{layout.Root, layout.releasesPath()} {
		// The units run with UMask=0077; set the mode explicitly so the
		// unprivileged controller can traverse to its binary.
		if err := os.Mkdir(path, 0o755); err == nil {
			if err := os.Chmod(path, 0o755); err != nil {
				return err
			}
		} else if !errors.Is(err, os.ErrExist) {
			return err
		}
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	return nil
}

// checkOwned rejects symlinks, foreign owners and group or world write.
func (layout Layout) checkOwned(path string, directory bool) error {
	info, err := os.Lstat(path)
	if err != nil {
		return err
	}
	stat, ok := info.Sys().(*syscall.Stat_t)
	if !ok || int(stat.Uid) != layout.Owner || info.Mode().Perm()&0o022 != 0 ||
		directory && !info.IsDir() || !directory && !info.Mode().IsRegular() {
		return fmt.Errorf("%w: %s", ErrUnsafe, path)
	}
	return nil
}

// Current returns the digest the current link points at, or "" when the
// link is absent.
func (layout Layout) Current() (string, error) { return layout.readLink(currentLink) }

// KnownGood returns the digest the known-good link points at, or "" when
// the link is absent: the last release a unit confirmed with a version
// proof. Nothing else moves it, so a restore, an unreadable record or the
// seed never make a release that has not proved itself the delegate.
func (layout Layout) KnownGood() (string, error) { return layout.readLink(knownGoodLink) }

func (layout Layout) readLink(name string) (string, error) {
	if err := layout.validate(); err != nil {
		return "", err
	}
	target, err := os.Readlink(filepath.Join(layout.Root, name))
	if errors.Is(err, os.ErrNotExist) {
		return "", nil
	}
	if err != nil {
		return "", err
	}
	digest, ok := strings.CutPrefix(target, releasesDir+"/")
	if !ok || !digestRE.MatchString(digest) {
		return "", fmt.Errorf("%w: %s link target %q", ErrUnsafe, name, target)
	}
	return digest, nil
}

func (layout Layout) VerifyRelease(digest string) error {
	if !digestRE.MatchString(digest) {
		return fmt.Errorf("%w: release digest", ErrInvalid)
	}
	for _, path := range []string{layout.Root, layout.releasesPath(), layout.ReleaseDir(digest)} {
		if err := layout.checkOwned(path, true); err != nil {
			return err
		}
	}
	path := layout.BinaryPath(digest)
	if err := layout.checkOwned(path, false); err != nil {
		return err
	}
	observed, _, err := hashFile(path)
	if err != nil {
		return err
	}
	if observed != digest {
		return fmt.Errorf("%w: release %s bytes changed", ErrUnsafe, digest)
	}
	return nil
}

// flipCurrent atomically repoints the current link at digest.
func (layout Layout) flipCurrent(digest string) error { return layout.flipLink(currentLink, digest) }

func (layout Layout) flipLink(name, digest string) error {
	temporary := filepath.Join(layout.Root, "."+name+"-"+digest[:16])
	_ = os.Remove(temporary)
	if err := os.Symlink(releasesDir+"/"+digest, temporary); err != nil {
		return err
	}
	if err := os.Rename(temporary, filepath.Join(layout.Root, name)); err != nil {
		_ = os.Remove(temporary)
		return err
	}
	return syncDir(layout.Root)
}

func hashFile(path string) (string, int64, error) {
	file, err := os.Open(path)
	if err != nil {
		return "", 0, err
	}
	defer file.Close()
	hash := sha256.New()
	size, err := io.Copy(hash, io.LimitReader(file, MaxBinaryBytes+1))
	if err != nil {
		return "", 0, err
	}
	if size > MaxBinaryBytes {
		return "", 0, fmt.Errorf("%w: binary exceeds %d bytes", ErrInvalid, MaxBinaryBytes)
	}
	return hex.EncodeToString(hash.Sum(nil)), size, nil
}

func syncDir(path string) error {
	directory, err := os.Open(path)
	if err != nil {
		return err
	}
	defer directory.Close()
	return directory.Sync()
}

// writeFileAtomic replaces path with data through a synced temporary file.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	directory := filepath.Dir(path)
	file, err := os.CreateTemp(directory, "."+filepath.Base(path)+"-*")
	if err != nil {
		return err
	}
	name := file.Name()
	defer os.Remove(name)
	if _, err := file.Write(data); err != nil {
		file.Close()
		return err
	}
	if err := file.Chmod(mode); err != nil {
		file.Close()
		return err
	}
	if err := file.Sync(); err != nil {
		file.Close()
		return err
	}
	if err := file.Close(); err != nil {
		return err
	}
	if err := os.Rename(name, path); err != nil {
		return err
	}
	return syncDir(directory)
}

// readBounded reads a small regular state file without following a final
// symlink. The open is nonblocking and the opened descriptor must be a
// regular file: a FIFO planted in a controller-writable directory would
// otherwise block the open, and with it every locked update command.
func readBounded(path string, maximum int64) ([]byte, error) {
	fd, err := syscall.Open(path, syscall.O_RDONLY|syscall.O_CLOEXEC|syscall.O_NOFOLLOW|syscall.O_NONBLOCK, 0)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	defer file.Close()
	info, err := file.Stat()
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, fmt.Errorf("%w: %s is not a regular file", ErrInvalid, path)
	}
	data, err := io.ReadAll(io.LimitReader(file, maximum+1))
	if err != nil {
		return nil, err
	}
	if int64(len(data)) > maximum {
		return nil, fmt.Errorf("%w: %s is too large", ErrInvalid, path)
	}
	return data, nil
}

// Lock serializes the root-run state changes on one node. The ExecStartPre
// prepare step, the watchdog timer and an operator stage or activate can run
// at the same moment; without it two rollbacks race on the current link's
// temporary name and on removing the activation record. The lock is held
// until the returned function is called.
func (layout Layout) Lock() (func(), error) {
	if err := layout.ensureDirs(); err != nil {
		return nil, err
	}
	path := filepath.Join(layout.Root, lockFile)
	fd, err := syscall.Open(path, syscall.O_RDWR|syscall.O_CREAT|syscall.O_CLOEXEC|syscall.O_NOFOLLOW, 0o600)
	if err != nil {
		return nil, &os.PathError{Op: "open", Path: path, Err: err}
	}
	file := os.NewFile(uintptr(fd), path)
	if err := layout.checkOwned(path, false); err != nil {
		file.Close()
		return nil, err
	}
	for {
		err = syscall.Flock(fd, syscall.LOCK_EX)
		if !errors.Is(err, syscall.EINTR) {
			break
		}
	}
	if err != nil {
		file.Close()
		return nil, &os.PathError{Op: "flock", Path: path, Err: err}
	}
	return func() { file.Close() }, nil
}

func (activation Activation) validate() error {
	if activation.Schema != ActivationSchema || !digestRE.MatchString(activation.Target) ||
		!digestRE.MatchString(activation.Previous) || activation.Target == activation.Previous ||
		!entityid.Valid(activation.ActivationID) || !unitRE.MatchString(activation.Unit) ||
		activation.ActivatedAt.IsZero() || !activation.Deadline.After(activation.ActivatedAt) ||
		activation.Deadline.Sub(activation.ActivatedAt) > MaxProofWindow {
		return fmt.Errorf("%w: activation record", ErrInvalid)
	}
	return nil
}

// Pending returns the pending activation, if any.
func (layout Layout) Pending() (Activation, bool, error) {
	data, exists, err := layout.pendingRecord()
	if err != nil || !exists {
		return Activation{}, false, err
	}
	activation, err := decodeActivation(data)
	if err != nil {
		return Activation{}, false, err
	}
	return activation, true, nil
}

func (layout Layout) pendingRecord() ([]byte, bool, error) {
	if err := layout.checkOwned(layout.activationPath(), false); errors.Is(err, os.ErrNotExist) {
		return nil, false, nil
	} else if err != nil {
		return nil, false, err
	}
	data, err := readBounded(layout.activationPath(), maxStateBytes)
	if err != nil {
		return nil, false, err
	}
	return data, true, nil
}

func decodeActivation(data []byte) (Activation, error) {
	var activation Activation
	if err := protocol.DecodeStrict(data, &activation, maxStateBytes); err != nil {
		return Activation{}, fmt.Errorf("%w: activation record: %w", ErrUnreadableActivation, err)
	}
	if err := activation.validate(); err != nil {
		return Activation{}, fmt.Errorf("%w: %w", ErrUnreadableActivation, err)
	}
	return activation, nil
}

func Activate(layout Layout, digest, unit string, now time.Time, window time.Duration) (Activation, error) {
	if window < MinProofWindow || window > MaxProofWindow || !unitRE.MatchString(unit) || now.IsZero() {
		return Activation{}, fmt.Errorf("%w: activation unit or proof window", ErrInvalid)
	}
	// An interrupted rollout restore is finished before the selection
	// changes again, so its recovery can never overwrite this activation.
	if err := layout.finishRestores(); err != nil {
		return Activation{}, err
	}
	if pending, exists, err := layout.Pending(); err != nil {
		return Activation{}, err
	} else if exists {
		if pending.Target == digest && pending.Unit == unit {
			// A retry passes the same gates as a fresh activation: a crash
			// after a rollback marked the target known bad must not
			// re-activate it, and unverified bytes never become current.
			if !now.Before(pending.Deadline) {
				return Activation{}, fmt.Errorf("%w: activation %s passed its deadline; the watchdog resolves it", ErrInvalid, pending.ActivationID)
			}
			if knownBad, err := layout.KnownBad(); err != nil {
				return Activation{}, err
			} else if knownBad[digest] {
				return Activation{}, ErrKnownBad
			}
			if err := layout.VerifyRelease(digest); err != nil {
				return Activation{}, err
			}
			return pending, layout.flipCurrent(digest)
		}
		return Activation{}, fmt.Errorf("%w: activation %s is still pending", ErrInvalid, pending.ActivationID)
	}
	if knownBad, err := layout.KnownBad(); err != nil {
		return Activation{}, err
	} else if knownBad[digest] {
		return Activation{}, ErrKnownBad
	}
	previous, err := layout.Current()
	if err != nil {
		return Activation{}, err
	}
	if previous == "" {
		return Activation{}, fmt.Errorf("%w: seed the baked release before activating another", ErrInvalid)
	}
	if previous == digest {
		return Activation{}, fmt.Errorf("%w: release is already current", ErrInvalid)
	}
	for _, release := range []string{previous, digest} {
		if err := layout.VerifyRelease(release); err != nil {
			return Activation{}, err
		}
	}

	activation := Activation{
		Schema: ActivationSchema, ActivationID: entityid.NewAt(now), Unit: unit,
		Target: digest, Previous: previous, ActivatedAt: now.UTC(), Deadline: now.UTC().Add(window),
	}
	encoded, err := protocol.EncodeJSON(activation)
	if err != nil {
		return Activation{}, err
	}
	if err := writeFileAtomic(layout.activationPath(), encoded, 0o644); err != nil {
		return Activation{}, err
	}
	if err := layout.flipCurrent(digest); err != nil {
		return activation, err
	}
	recordActivation(activation)
	return activation, nil
}

func (layout Layout) KnownBad() (map[string]bool, error) {
	data, err := readBounded(layout.knownBadPath(), maxStateBytes)
	if errors.Is(err, os.ErrNotExist) {
		return map[string]bool{}, nil
	}
	if err != nil {
		return nil, err
	}
	var state knownBadState
	if err := protocol.DecodeStrict(data, &state, maxStateBytes); err != nil {
		return nil, err
	}
	known := make(map[string]bool, len(state.Digests))
	for _, digest := range state.Digests {
		if !digestRE.MatchString(digest) {
			return nil, fmt.Errorf("%w: known-bad digest", ErrInvalid)
		}
		known[digest] = true
	}
	return known, nil
}

func (layout Layout) AcceptedEpoch() (uint64, error) {
	if err := layout.checkOwned(layout.epochPath(), false); errors.Is(err, os.ErrNotExist) {
		return 0, nil
	} else if err != nil {
		return 0, err
	}
	data, err := readBounded(layout.epochPath(), 64)
	if err != nil {
		return 0, err
	}
	epoch, err := strconv.ParseUint(strings.TrimSpace(string(data)), 10, 64)
	if err != nil || epoch == 0 {
		return 0, fmt.Errorf("%w: accepted authority epoch", ErrInvalid)
	}
	return epoch, nil
}

// AdmitEpoch durably records epoch as accepted before the caller acts on
// an order from it, and refuses an epoch older than one already accepted.
// The caller holds Lock across AdmitEpoch and the effects it fences.
func (layout Layout) AdmitEpoch(epoch uint64) error {
	if epoch == 0 {
		return fmt.Errorf("%w: authority epoch", ErrInvalid)
	}
	accepted, err := layout.AcceptedEpoch()
	if err != nil {
		return err
	}
	switch {
	case epoch < accepted:
		return ErrStaleEpoch
	case epoch == accepted:
		return nil
	}
	if err := layout.ensureDirs(); err != nil {
		return err
	}
	return writeFileAtomic(layout.epochPath(), fmt.Appendf(nil, "%d\n", epoch), 0o644)
}

func (layout Layout) restartMarkerPath(unit string) string {
	return filepath.Join(layout.Root, restartMarkerPrefix+unit)
}

// markRestartPending records that unit must restart onto the restored
// release. It is written before the activation record is removed, so no
// interruption can lose both.
func (layout Layout) markRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	return writeFileAtomic(layout.restartMarkerPath(unit), []byte(unit+"\n"), 0o644)
}

// RestartPending reports whether a rollback of unit has not been followed by
// a restart yet. The caller holds Lock.
func (layout Layout) RestartPending(unit string) (bool, error) {
	if !unitRE.MatchString(unit) {
		return false, fmt.Errorf("%w: unit", ErrInvalid)
	}
	err := layout.checkOwned(layout.restartMarkerPath(unit), false)
	if errors.Is(err, os.ErrNotExist) {
		return false, nil
	}
	return err == nil, err
}

// ClearRestartPending removes the marker once unit restarted. Prepare calls
// it at every unit start; the watchdog after a successful restart. The caller
// holds Lock.
func (layout Layout) ClearRestartPending(unit string) error {
	if !unitRE.MatchString(unit) {
		return fmt.Errorf("%w: unit", ErrInvalid)
	}
	if err := os.Remove(layout.restartMarkerPath(unit)); err != nil && !errors.Is(err, os.ErrNotExist) {
		return err
	}
	return nil
}

func (layout Layout) finishRestores() error {
	intents, err := layout.PendingRestores()
	if err != nil {
		return err
	}
	for _, intent := range intents {
		if err := layout.finishRestore(intent.Unit); err != nil {
			return err
		}
	}
	return nil
}

// PendingRestores reads owned, strictly validated restore intents without effects.
func (layout Layout) PendingRestores() ([]RestoreIntent, error) {
	if err := layout.validate(); err != nil {
		return nil, err
	}
	if err := layout.checkOwned(layout.Root, true); errors.Is(err, os.ErrNotExist) {
		return nil, nil
	} else if err != nil {
		return nil, err
	}
	entries, err := os.ReadDir(layout.Root)
	if err != nil {
		return nil, err
	}
	var intents []RestoreIntent
	for _, entry := range entries {
		unit, ok := strings.CutPrefix(entry.Name(), restoreIntentPrefix)
		if !ok {
			continue
		}
		unit, ok = strings.CutSuffix(unit, ".json")
		if !ok || !unitRE.MatchString(unit) {
			return nil, fmt.Errorf("%w: restore intent %q", ErrUnsafe, entry.Name())
		}
		if _, pending, err := layout.Pending(); err != nil {
			return nil, err
		} else if pending {
			return nil, fmt.Errorf("%w: restore intent of %s next to a pending activation", ErrUnsafe, unit)
		}
		intent, err := layout.readRestoreIntent(unit)
		if err != nil {
			return nil, err
		}
		intents = append(intents, intent)
	}
	return intents, nil
}

func (layout Layout) MarkRestartPending(unit string) error {
	return layout.markRestartPending(unit)
}

func VerifyCurrent(envelope Envelope, expected Scope, keys Keyring, now time.Time, policy Policy) ([]byte, error) {
	if !validTime(now) || policy.MaxLifetime <= 0 || policy.ClockSkew < 0 {
		return nil, fmt.Errorf("%w: invalid verification policy", ErrInvalid)
	}
	if err := verifySignature(envelope, expected, keys, policy.MaxLifetime); err != nil {
		return nil, err
	}
	if envelope.IssuedAt.Sub(now) > policy.ClockSkew {
		return nil, ErrNotYetValid
	}
	if !now.Before(envelope.ExpiresAt) {
		return nil, ErrExpired
	}
	return bytesClone(envelope.Payload), nil
}

func TestRuntimePriorityCLIProcess(t *testing.T) {
	if os.Getenv("TS_RUNTIME_PRIORITY_CLI_PROCESS") != "1" {
		return
	}
	separator := slices.Index(os.Args, "--")
	if separator < 0 {
		os.Exit(3)
	}
	if err := Run(t.Context(), os.Args[separator+1:], os.Stdout); err != nil {
		fmt.Fprintf(os.Stderr, "%s: %v\n", ErrorType(err), err)
		os.Exit(2)
	}
	os.Exit(0)
}

func runtimeCLI(t *testing.T, args ...string) ([]byte, error) {
	t.Helper()
	executable, err := os.Executable()
	if err != nil {
		t.Fatal(err)
	}
	ctx, cancel := context.WithTimeout(t.Context(), 10*time.Second)
	defer cancel()
	cmd := exec.CommandContext(ctx, executable, append([]string{"-test.run=^TestRuntimePriorityCLIProcess$", "--"}, args...)...)
	cmd.Env = append(os.Environ(), "TS_RUNTIME_PRIORITY_CLI_PROCESS=1", "GORACE=atexit_sleep_ms=0")
	cmd.WaitDelay = time.Second
	return cmd.CombinedOutput()
}

func parseOptions(args []string) (Object, error) {
	o := Object{}
	for i := 0; i < len(args); i++ {
		arg := args[i]
		if !strings.HasPrefix(arg, "--") {
			return nil, fmt.Errorf("unexpected positional argument %s", arg)
		}
		key := strings.ReplaceAll(strings.TrimPrefix(arg, "--"), "-", "_")
		if _, exists := o[key]; exists {
			return nil, fmt.Errorf("repeated option %s", arg)
		}
		if key == "retain_evidence" {
			o[key] = true
			continue
		}
		i++
		if i >= len(args) {
			return nil, fmt.Errorf("%s requires a value", arg)
		}
		value := args[i]
		if strings.HasSuffix(key, "_bytes") || key == "database_pid" {
			n, e := strconv.ParseInt(value, 10, 64)
			if e != nil {
				return nil, fmt.Errorf("%s must be signed integer", arg)
			}
			o[key] = n
		} else {
			o[key] = value
		}
	}
	return o, nil
}

func Run(ctx context.Context, args []string, out io.Writer) (err error) {
	defer recoverError(&err)
	if len(args) == 0 {
		return fmt.Errorf("runtime-priority requires qualify, pressure, probe-admission, adapter, or remote")
	}
	command := args[0]
	args = args[1:]
	switch command {

	case "pressure":
		if len(args) == 0 {
			return fmt.Errorf("pressure requires dry-run, run, or stress-worker")
		}
		mode := args[0]
		args = args[1:]
		if mode == "resource-worker" {
			return RunResourceWorker(ctx, args, out)
		}
		options, e := parseOptions(args)
		if e != nil {
			return e
		}
		manifest, wire, e := LoadJSON(text(options["manifest"], "--manifest"), 1<<20)
		if e != nil {
			return e
		}
		switch mode {
		case "dry-run":
			plan, e := DryRun(manifest, Hash(wire))
			if e != nil {
				return e
			}
			_, e = out.Write(pretty(plan))
			return e
		case "run":
			status, e := RunQualification(ctx, manifest, wire, Hash(wire), text(options["evidence_dir"], "--evidence-dir"), nil, out)
			if e != nil {
				return e
			}
			if status != 0 {
				return fmt.Errorf("runtime priority qualification did not pass")
			}
			return nil
		case "stress-worker":
			assigned := text(options["assigned_pressure_cgroup"], "--assigned-pressure-cgroup")
			if str(sub(sub(manifest, "pressure"), "workload_cgroup"), "path") != assigned {
				return fmt.Errorf("stress worker assigned scope differs from manifest")
			}
			return RunStressWorker(ctx, manifest, text(options["expected_native_runner_cgroup"], "--expected-native-runner-cgroup"), text(options["protected_database_cgroup"], "--protected-database-cgroup"), text(options["run_id"], "--run-id"), options["retain_evidence"] == true, out)
		default:
			return fmt.Errorf("unsupported pressure mode %s", mode)
		}
	default:
		return fmt.Errorf("unsupported runtime-priority command %s", command)
	}
}

func validateScope(v any, label string) Object {
	o := obj(v, label)
	if !exact(o, "cluster_id", "tenant_id", "database_id", "shard_id", "member_id", "incarnation") {
		fail("%s must contain exactly the alpha member scope fields", label)
	}
	for _, k := range []string{"cluster_id", "incarnation"} {
		if value := str(o, k); !processNonceRE.MatchString(value) || value == strings.Repeat("0", 32) {
			fail("%s.%s must be a nonzero lowercase 128-bit token", label, k)
		}
	}
	for _, k := range []string{"tenant_id", "database_id", "member_id"} {
		if !entityid.Valid(str(o, k)) {
			fail("%s.%s must be a canonical uppercase ULID", label, k)
		}
	}
	num(o["shard_id"], label+".shard_id", 1)
	return o
}
func validateAuthority(v any, label string) Object {
	o := obj(v, label)
	if !exact(o, "epoch", "configuration_id", "certificate_sha256", "tls_leaf_sha256") {
		fail("%s must contain exactly the alpha authority fields", label)
	}
	num(o["epoch"], label+".epoch", 1)
	for _, k := range []string{"configuration_id", "certificate_sha256", "tls_leaf_sha256"} {
		if !hashRE.MatchString(str(o, k)) {
			fail("%s.%s must be a lowercase SHA-256 digest", label, k)
		}
	}
	return o
}
func validateManaged(v any) Object {
	m := obj(v, "managed_member")
	if !exact(m, "source", "peer", "document", "acknowledgment_profile") || str(m, "acknowledgment_profile") != "object_durable" {
		fail("managed_member fields must pin source, peer, document, and ObjectDurable acknowledgment_profile")
	}
	for _, label := range []string{"source", "peer"} {
		row := sub(m, label)
		if !exact(row, "cell", "node", "environment", "role", "scope", "authority") {
			fail("managed_member.%s fields do not match alpha host report", label)
		}
		for _, k := range []string{"cell", "node", "environment", "role"} {
			text(row[k], "managed_member."+label+"."+k)
		}
		if str(row, "role") != "terrabase" {
			fail("managed_member.%s.role must be terrabase", label)
		}
		validateScope(row["scope"], label+".scope")
		validateAuthority(row["authority"], label+".authority")
	}
	a, b := sub(m, "source"), sub(m, "peer")
	if a["cell"] != b["cell"] || a["environment"] != b["environment"] || a["node"] == b["node"] {
		fail("source and peer must be distinct nodes in one cell and environment")
	}
	sa, sb := sub(a, "scope"), sub(b, "scope")
	for _, k := range []string{"cluster_id", "tenant_id", "database_id", "shard_id"} {
		if !same(sa[k], sb[k]) {
			fail("source and peer scopes disagree on %s", k)
		}
	}
	if sa["member_id"] == sb["member_id"] || sa["incarnation"] == sb["incarnation"] {
		fail("source and peer require distinct member IDs and incarnations")
	}
	d := sub(m, "document")
	if !exact(d, "collection_id", "schema_generation", "schema_digest", "utf8_field") || !entityid.Valid(str(d, "collection_id")) || !hashRE.MatchString(str(d, "schema_digest")) {
		fail("managed_member.document does not match alpha document transaction input")
	}
	num(d["schema_generation"], "schema_generation", 1)
	text(d["utf8_field"], "managed_member.document.utf8_field")
	return m
}
func validateHTTPS(value any, label string) {
	s := text(value, label)
	u, e := url.Parse(s)
	if e != nil || u.Scheme != "https" || u.Hostname() == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" || (u.Path != "" && u.Path != "/") {
		fail("%s must be an origin-only HTTPS URL without userinfo or query", label)
	}
}
func validateMetrics(value any, label string) {
	s := text(value, label)
	u, e := url.Parse(s)
	if e != nil {
		fail("%s must be a loopback HTTP /metrics URL", label)
	}
	address, e := netip.ParseAddr(u.Hostname())
	if e != nil || !address.IsLoopback() || u.Scheme != "http" || u.Path != "/metrics" || u.User != nil || u.RawQuery != "" || u.Fragment != "" {
		fail("%s must be a loopback HTTP /metrics URL", label)
	}
}
func privateReason(path, label string, reasons *[]string) {
	e := func() (err error) {
		defer recoverError(&err)
		if !filepath.IsAbs(path) {
			fail("%s path must be absolute", label)
		}
		privateFile(path, label)
		return
	}()
	if e != nil {
		*reasons = append(*reasons, e.Error())
	}
}
func validateProbeAdmission(m Object, reasons *[]string) {
	pin := sub(m, "probe_admission")
	if !exact(pin, "receipt_path", "receipt_sha256") {
		fail("probe_admission must pin one exact CI readback receipt")
	}
	before := len(*reasons)
	pinReason(pin, "receipt_path", "receipt_sha256", "D15 probe admission", false, reasons)
	if len(*reasons) > before {
		return
	}
	r, _ := load(str(pin, "receipt_path"), 16384)
	if !exact(r, "schema", "repository", "source_revision", "source_tree", "release_tag", "run_id", "run_number", "workflow", "job", "job_id", "attempt", "probe_asset", "probe_bytes", "probe_sha256", "publication_sha256", "qualification_sha256", "run_detail_sha256", "job_log_sha256") || str(r, "schema") != "terrascale.d15.probe-admission/v1" || str(r, "repository") != "TerraScale/ts-orchestrator" || r["source_revision"] != m["repository_revision"] || str(r, "workflow") != "ci.yml" || str(r, "job") != ProducerJob || str(r, "probe_asset") != ProbeAsset || r["probe_sha256"] != sub(sub(m, "transport"), "runtime")["qualify_sha256"] {
		fail("D15 probe admission differs from exact source, CI job, or probe pin")
	}
	if !gitRE.MatchString(str(r, "source_tree")) {
		fail("D15 probe admission lacks exact source and readback hashes")
	}
	for _, k := range []string{"publication_sha256", "qualification_sha256", "run_detail_sha256", "job_log_sha256"} {
		if !hashRE.MatchString(str(r, k)) {
			fail("D15 probe admission lacks exact source and readback hashes")
		}
	}
	for _, k := range []string{"run_id", "run_number", "job_id", "attempt", "probe_bytes"} {
		num(r[k], "D15 probe admission "+k, 1)
	}
	if n(r, "probe_bytes") > MaxProbeBytes || str(r, "release_tag") != fmt.Sprintf("ci-%s-run-%d", str(r, "source_revision"), n(r, "run_id")) {
		fail("D15 probe admission has invalid release or bounded asset size")
	}
}
func validateTransport(m Object, reasons *[]string) {
	transport := sub(m, "transport")
	operator := sub(transport, "operator")
	pinReason(operator, "executable_path", "executable_sha256", "operator executable pin", true, reasons)
	pinReason(operator, "config_path", "config_sha256", "operator hosts config", false, reasons)
	ssh := sub(transport, "ssh")
	pinReason(ssh, "executable_path", "executable_sha256", "SSH executable pin", true, reasons)
	targets := sub(ssh, "targets")
	if !exact(targets, "source", "peer", "controller") {
		fail("transport.ssh.targets must contain source, peer, and controller targets")
	}
	ids := map[string]bool{}
	for _, label := range []string{"source", "peer", "controller"} {
		t := sub(targets, label)
		if !exact(t, "address", "user", "port", "host_key_alias", "known_hosts_path", "known_hosts_sha256", "identity_file_path", "oci_instance_id") {
			fail("transport.ssh.targets.%s fields differ from pinned SSH settings", label)
		}
		address := text(t["address"], label+" SSH address")
		if strings.HasPrefix(address, "-") || !regexp.MustCompile(`^[A-Za-z0-9.:%_-]{1,253}$`).MatchString(address) {
			fail("transport.ssh.targets.%s.address is not safe SSH host address", label)
		}
		if _, e := netip.ParseAddr(address); e != nil {
			for part := range strings.SplitSeq(address, ".") {
				if !regexp.MustCompile(`^[A-Za-z0-9](?:[A-Za-z0-9-]{0,61}[A-Za-z0-9])?$`).MatchString(part) {
					fail("transport.ssh.targets.%s.address is not valid host or IP address", label)
				}
			}
		}
		if !regexp.MustCompile(`^[A-Za-z_][A-Za-z0-9_-]{0,31}$`).MatchString(str(t, "user")) {
			fail("unsafe SSH account name")
		}
		if num(t["port"], label+" SSH port", 1) > 65535 {
			fail("SSH port must not exceed 65535")
		}
		text(t["host_key_alias"], label+" host key alias")
		id := text(t["oci_instance_id"], label+" OCI instance ID")
		if !instanceRE.MatchString(id) {
			*reasons = append(*reasons, label+" SSH instance ID must be real OCI instance OCID")
		}
		if ids[id] {
			fail("SSH targets must pin distinct OCI instance IDs")
		}
		ids[id] = true
		pinReason(t, "known_hosts_path", "known_hosts_sha256", label+" SSH known_hosts", false, reasons)
		privateReason(str(t, "identity_file_path"), label+" SSH identity file", reasons)
	}
	if sub(targets, "source")["oci_instance_id"] != sub(m, "identity")["oci_instance_id"] {
		fail("source SSH target OCI instance ID differs from target identity pin")
	}
	if sub(targets, "controller")["oci_instance_id"] != sub(m, "controller_identity")["oci_instance_id"] {
		fail("controller SSH target OCI instance ID differs from its target identity pin")
	}
	https := sub(transport, "https")
	for _, label := range []string{"source", "peer"} {
		validateHTTPS(https[label+"_base_url"], label+" HTTPS URL")
		validateMetrics(https[label+"_metrics_url"], label+" metrics URL")
		privateReason(str(https, label+"_credential_file"), label+" credential file", reasons)
	}
	pinReason(https, "ca_bundle_path", "ca_bundle_sha256", "TerraBase client CA bundle", false, reasons)
	runtime := sub(transport, "runtime")
	if !same(runtime["service_names"], Object{"host": HostUnit, "controller": ControllerUnit}) {
		fail("transport.runtime.service_names must pin exact alpha host/controller units")
	}
	for _, k := range []string{"sudo_path", "remote_executable_path", "qualify_path", "stress_launcher_path", "systemctl_path", "systemd_run_path", "journalctl_path"} {
		s := text(runtime[k], "transport.runtime."+k)
		if !regexp.MustCompile(`^/[A-Za-z0-9._/-]+$`).MatchString(s) {
			fail("transport.runtime.%s must be absolute safe executable path", k)
		}
	}
	hash := text(runtime["qualify_sha256"], "transport.runtime.qualify_sha256")
	if !hashRE.MatchString(hash) {
		fail("transport.runtime.qualify_sha256 must pin exact CI probe bytes")
	}
	expected := fmt.Sprintf("/run/terrascale-d15/probes/%s/%s/qualify", m["repository_revision"], hash)
	if str(runtime, "qualify_path") != expected {
		fail("qualify_path must use exact root-owned temporary staging path")
	}
	if str(runtime, "remote_executable_path") != expected {
		fail("remote action executable must use exact admitted probe staging path")
	}
	if !regexp.MustCompile(`^[A-Za-z0-9_.@:-]+\.slice$`).MatchString(str(runtime, "workload_slice")) {
		fail("transport.runtime.workload_slice must be exact systemd .slice unit")
	}
	if str(runtime, "stress_launcher_contract") != "terrascale.d15.cgroup-launch/v1" {
		*reasons = append(*reasons, "target native pressure launcher must implement terrascale.d15.cgroup-launch/v1")
	}
	if !hashRE.MatchString(str(runtime, "stress_launcher_sha256")) {
		*reasons = append(*reasons, "target native pressure launcher SHA-256 missing or malformed")
	}
	a := sub(m, "adapter")
	if !exact(a, "executable_path", "executable_sha256", "deadlines_seconds") {
		fail("adapter fields must be exactly pinned native executable and deadlines")
	}
	pinReason(a, "executable_path", "executable_sha256", "alpha adapter executable pin", true, reasons)
	contract := sub(m, "adapter_contract")
	if a["executable_path"] != contract["source_path"] || a["executable_sha256"] != contract["source_sha256"] {
		*reasons = append(*reasons, "adapter executable pin differs from frozen alpha contract source pin")
	}
	roles := slices.Clone(baseRoles)
	scenario := str(sub(m, "pressure"), "scenario")
	if scenario == "terrabase_process" || scenario == "host_manager_sigkill" {
		roles = append(roles, "failure_inject")
	}
	if scenario == "terrabase_oom" {
		roles = append(roles, "kernel_oom_evidence")
	}
	d := sub(a, "deadlines_seconds")
	if !exact(d, roles...) {
		*reasons = append(*reasons, "alpha adapter deadlines must cover exactly required scenario roles")
		for _, role := range roles {
			if _, ok := d[role]; !ok {
				*reasons = append(*reasons, fmt.Sprintf("required adapter '%s' is missing", role))
			}
		}
	}
	for role, v := range d {
		deadline := num(v, "adapter.deadlines_seconds."+role, 1)
		if deadline > 300 {
			*reasons = append(*reasons, "adapter deadline exceeds 300 seconds")
		}
		if role == "database_progress" && !same(v, contract["database_progress_deadline_seconds"]) {
			*reasons = append(*reasons, "database progress deadline differs from frozen alpha contract")
		}
	}
}
func ValidateManifest(m Object, dry, allocations bool) (reasons []string, err error) {
	defer recoverError(&err)
	reasons = []string{}
	if str(m, "schema") != Schema {
		fail("manifest schema must be %q", Schema)
	}
	id := sub(m, "identity")
	for _, k := range identityKeys {
		text(id[k], "identity."+k)
	}
	if !instanceRE.MatchString(str(id, "oci_instance_id")) {
		reasons = append(reasons, "identity.oci_instance_id must be a real OCI instance OCID")
	}
	if !imageRE.MatchString(str(id, "image_id")) {
		reasons = append(reasons, "identity.image_id must be actual imported OCI image OCID")
	}
	if str(id, "architecture") != "aarch64" {
		fail("D15 target architecture must be aarch64")
	}
	controller := sub(m, "controller_identity")
	if !exact(controller, identityKeys...) {
		fail("controller_identity must pin exact controller guest identity")
	}
	for _, k := range identityKeys {
		text(controller[k], "controller_identity."+k)
	}
	if str(controller, "architecture") != "aarch64" || controller["cell"] != id["cell"] || controller["environment"] != id["environment"] || controller["oci_instance_id"] == id["oci_instance_id"] {
		fail("controller identity must pin distinct ARM guest in same cell/environment")
	}
	if !instanceRE.MatchString(str(controller, "oci_instance_id")) {
		reasons = append(reasons, "controller_identity.oci_instance_id must be real OCI instance OCID")
	}
	if !imageRE.MatchString(str(controller, "image_id")) {
		reasons = append(reasons, "controller_identity.image_id must be actual imported OCI image OCID")
	}
	member := validateManaged(m["managed_member"])
	if sub(member, "source")["cell"] != id["cell"] || sub(member, "source")["environment"] != id["environment"] {
		fail("identity cell/environment differs from signed source member")
	}
	if !gitRE.MatchString(str(m, "repository_revision")) {
		fail("repository_revision must pin full 40-character Git source ID")
	}
	auth := sub(m, "authorization")
	contract := sub(m, "adapter_contract")
	if auth["live_stress_authorized"] != true {
		reasons = append(reasons, "OCI owner has not explicitly authorized live pressure")
	}
	pinReason(auth, "owner_handoff_path", "owner_handoff_sha256", "OCI owner handoff", false, &reasons)
	if contract["frozen"] != true {
		reasons = append(reasons, "alpha host, database, target, and recovery adapter contract is not frozen")
	}
	if str(contract, "schema") != "terrascale.d15.adapter-contract/v5" || num(contract["version"], "adapter contract version", 1) != 5 {
		reasons = append(reasons, "adapter contract must declare v5 schema and version 5")
	}
	text(contract["id"], "adapter_contract.id")
	for k, want := range map[string]string{"database_frontier_binding": "object_durable.event{database,shard,replica,incarnation,sequence};serving_proof.v1/same_scope/v1", "host_status_source": "operator-hosts-json/controller-admitted/read-only/v1", "managed_process_witness": "accepted-managed-report+proc-stat+cgroup+boot-id/v1", "pressure_survival_policy": "all-pressure-workers-through-duration/v1", "oom_journal_format": "systemd-journal-kernel-oom/v1"} {
		if str(contract, k) != want {
			reasons = append(reasons, "adapter contract must pin "+k)
		}
	}
	for _, k := range []string{"database_progress_deadline_seconds", "oom_event_window_seconds"} {
		v := num(contract[k], k, 1)
		if v > 300 {
			reasons = append(reasons, "adapter contract "+k+" exceeds 300 seconds")
		}
	}
	if num(contract["host_report_max_age_seconds"], "host report maximum age", 1) != 30 {
		reasons = append(reasons, "adapter contract must pin 30-second host report freshness")
	}
	if num(contract["target_witness_max_age_ms"], "target witness age", 1) > 1000 {
		reasons = append(reasons, "adapter contract target witness age exceeds 1000 milliseconds")
	}
	pinReason(contract, "source_path", "source_sha256", "adapter contract", true, &reasons)
	validateProbeAdmission(m, &reasons)
	q := sub(m, "qualification")
	for _, k := range qualificationKeys {
		num(q[k], "qualification."+k, 1)
	}
	page := num(m["page_size_bytes"], "page_size_bytes", 1)
	if page&(page-1) != 0 {
		fail("page_size_bytes must be positive power of two")
	}
	for _, k := range qualificationKeys[:8] {
		if n(q, k)%page != 0 {
			fail("profile memory values must be page aligned")
		}
	}
	if n(q, qualificationKeys[0]) > n(q, qualificationKeys[1]) || n(q, qualificationKeys[2]) > n(q, qualificationKeys[3]) || n(q, qualificationKeys[4]) > n(q, qualificationKeys[5]) || n(q, qualificationKeys[4]) < n(q, qualificationKeys[0])+n(q, qualificationKeys[2]) || n(q, qualificationKeys[5]) < n(q, qualificationKeys[1])+n(q, qualificationKeys[3]) || n(q, qualificationKeys[5]) > n(q, "system_reserve_bytes") {
		fail("service and system.slice floor values violate signed reserve relationship")
	}
	cq := sub(m, "controller_qualification")
	if !exact(cq, controllerKeys...) {
		fail("controller_qualification must pin exact controller memory allocations")
	}
	for _, k := range controllerKeys {
		if num(cq[k], "controller_qualification."+k, 1)%page != 0 {
			fail("controller_qualification.%s must be page aligned", k)
		}
	}
	if n(cq, controllerKeys[0]) > n(cq, controllerKeys[1]) || n(cq, controllerKeys[2]) < n(cq, controllerKeys[0]) || n(cq, controllerKeys[3]) < n(cq, controllerKeys[1]) || n(cq, controllerKeys[2]) > n(cq, controllerKeys[3]) || n(cq, controllerKeys[3]) > n(cq, "system_reserve_bytes") {
		fail("controller service and system.slice floors violate signed reserve")
	}
	for _, group := range []string{"memory_floor_evidence", "controller_memory_floor_evidence"} {
		floors := sub(m, group)
		keys := []string{"host_service", "controller_service", "system_slice"}
		if group == "controller_memory_floor_evidence" {
			keys = []string{"controller_service", "system_slice"}
			if !exact(floors, keys...) {
				fail("controller floor evidence must pin controller service and slice sources")
			}
		}
		for _, scope := range keys {
			e := sub(floors, scope)
			basis := str(e, "basis")
			if basis != "allocation" && basis != "measured" {
				fail("%s.%s.basis must be measured or allocation", group, scope)
			}
			text(e["source"], group+"."+scope+".source")
			timestamp(e["observed_at_utc"], group+"."+scope+".observed_at_utc")
			pinReason(e, "source_path", "source_sha256", scope+" floor evidence", false, &reasons)
			if basis != "measured" && !allocations {
				reasons = append(reasons, scope+" memory floors are allocations, not measured floors")
			}
		}
	}
	validatePressurePlan(sub(m, "pressure"), q, page, dry)
	validateTransport(m, &reasons)
	if !dry && len(reasons) > 0 {
		fail("live qualification is unqualified: %s", strings.Join(reasons, "; "))
	}
	return
}
func validatePressurePlan(p, q Object, page int64, dry bool) {
	scenario := text(p["scenario"], "pressure.scenario")
	if !slices.Contains([]string{"management_stability", "terrabase_process", "terrabase_oom", "host_manager_sigkill"}, scenario) {
		fail("unsupported pressure scenario")
	}
	duration := num(p["duration_seconds"], "pressure.duration_seconds", 1)
	interval := num(p["sample_interval_seconds"], "pressure.sample_interval_seconds", 1)
	if duration > 900 {
		fail("pressure.duration_seconds must not exceed 900")
	}
	if interval >= duration {
		fail("sample interval must be below pressure duration")
	}
	if (duration+interval-1)/interval > 180 {
		fail("pressure plan exceeds 180 sample harness limit")
	}
	if scenario != "management_stability" {
		event := num(p["scenario_event_after_seconds"], "pressure.scenario_event_after_seconds", 1)
		if event >= duration || event <= interval {
			fail("scenario event time must allow one sample and be below pressure duration")
		}
	}
	for _, k := range []string{"cpu_workers", "memory_bytes", "memory_headroom_bytes", "io_workers", "io_file_bytes", "io_total_bytes", "io_bytes_per_second", "io_block_bytes"} {
		num(p[k], "pressure."+k, 1)
	}
	limits := map[string]int64{"cpu_workers": 64, "io_workers": 32, "io_file_bytes": 2 << 30, "io_total_bytes": 64 << 30, "io_bytes_per_second": 128 << 20}
	for k, limit := range limits {
		if n(p, k) > limit {
			fail("pressure.%s must not exceed %d", k, limit)
		}
	}
	memory := n(p, "memory_bytes") + n(p, "memory_headroom_bytes")
	if memory > 16<<30 {
		fail("memory payload plus headroom exceeds maximum")
	}
	if memory > n(q, "allocatable_memory_bytes") {
		fail("memory payload plus headroom exceeds signed allocatable memory")
	}
	if n(p, "io_file_bytes") > 4<<30/n(p, "io_workers") {
		fail("pressure I/O scratch allocation exceeds maximum")
	}
	block := n(p, "io_block_bytes")
	if block&(block-1) != 0 {
		fail("pressure.io_block_bytes must be power of two")
	}
	if block > n(p, "io_file_bytes") || block > n(p, "io_total_bytes") || n(p, "io_file_bytes")%block != 0 {
		fail("pressure I/O bounds must be multiples of at least one block")
	}
	if n(p, "io_total_bytes") < n(p, "io_bytes_per_second")*duration {
		fail("finite I/O budget must cover configured rate for full duration")
	}
	if !filepath.IsAbs(text(p["io_directory"], "pressure.io_directory")) {
		fail("pressure.io_directory must be absolute")
	}
	cg := sub(p, "workload_cgroup")
	parent := text(cg["parent_path"], "pressure.workload_cgroup.parent_path")
	if !safePath(parent) || !inside(parent, CgroupRoot) {
		fail("pressure workload parent must identify existing native workload slice")
	}
	f := strings.Fields(text(cg["cpu_max"], "pressure.workload_cgroup.cpu_max"))
	if len(f) != 2 || !decimalRE.MatchString(f[0]) || integerText(f[0], "CPU quota") == 0 || f[1] != "100000" {
		fail("pressure workload cgroup cpu_max must be '<quota> 100000' for systemd CPUQuota")
	}
	num(cg["memory_max_bytes"], "pressure memory.max", 1)
	num(cg["io_weight"], "pressure io.weight", 1)
	device := text(cg["io_device"], "pressure IO device")
	if !regexp.MustCompile(`^[0-9]+:[0-9]+$`).MatchString(device) {
		fail("pressure I/O device must be block major:minor pair")
	}
	if !dry && strings.HasPrefix(device, "0:") {
		fail("live pressure I/O must target block-backed filesystem")
	}
	if memory > n(cg, "memory_max_bytes") {
		fail("memory payload plus explicit headroom exceeds the pressure cgroup memory.max")
	}
	if scenario == "terrabase_oom" {
		fault := sub(p, "oom_fault")
		if !exact(fault, "target_memory_max_bytes", "deadline_seconds") {
			fail("pressure.oom_fault must pin exact temporary native-role cap and deadline")
		}
		cap := num(fault["target_memory_max_bytes"], "pressure.oom_fault.target_memory_max_bytes", page)
		if cap%page != 0 {
			fail("OOM target memory.max must be page aligned")
		}
		if cap >= n(q, "database_memory_max_bytes") {
			fail("OOM target memory.max must be below the signed TerraBase role cap")
		}
		if num(fault["deadline_seconds"], "pressure.oom_fault.deadline_seconds", 1) > 30 {
			fail("bounded OOM fault deadline must not exceed 30 seconds")
		}
	} else if _, ok := p["oom_fault"]; ok {
		fail("oom_fault supported only by terrabase_oom scenario")
	}
}
func DryRun(m Object, hash string) (plan Object, err error) {
	reasons, e := ValidateManifest(m, true, false)
	if e != nil {
		return nil, e
	}
	slices.Sort(reasons)
	reasons = slices.Compact(reasons)
	roles := slices.Clone(baseRoles)
	scenario := str(sub(m, "pressure"), "scenario")
	if scenario == "terrabase_process" || scenario == "host_manager_sigkill" {
		roles = append(roles, "failure_inject")
	}
	if scenario == "terrabase_oom" {
		roles = append(roles, "kernel_oom_evidence")
	}
	slices.Sort(roles)
	a := sub(m, "adapter")
	plan = Object{"schema": Schema, "mode": "DRY_RUN_ONLY", "qualification_status": "UNQUALIFIED", "commands_executed": false, "pressure_started": false, "manifest_sha256": hash, "identity": m["identity"], "controller_identity": m["controller_identity"], "controller_memory_floor_evidence": m["controller_memory_floor_evidence"], "adapter_source": Object{"executable_path": a["executable_path"], "executable_sha256": a["executable_sha256"]}, "planned_adapter_roles": roles, "required_adapter_roles": roles, "missing_or_unqualified": reasons, "resource_plan": m["pressure"]}
	return
}

func (e *DomainError) Error() string { return e.Message }
func fail(format string, a ...any)   { panic(&DomainError{"HarnessError", fmt.Sprintf(format, a...)}) }
func qfail(format string, a ...any) {
	panic(&DomainError{"QualificationError", fmt.Sprintf(format, a...)})
}
func recoverError(err *error) {
	if p := recover(); p != nil {
		if e, ok := p.(error); ok {
			if _, domain := errors.AsType[*DomainError](e); domain {
				*err = errors.Join(*err, e)
				return
			}
		}
		panic(p)
	}
}
func ErrorType(err error) string {
	if e, ok := errors.AsType[*DomainError](err); ok {
		return e.Domain
	}
	return "error"
}

func inside(path, root string) bool {
	rel, e := filepath.Rel(root, path)
	return e == nil && rel != "." && rel != ".." && !strings.HasPrefix(rel, "../")
}
func safePath(path string) bool {
	return filepath.IsAbs(path) && filepath.Clean(path) == path && !strings.Contains(path, "/../")
}
func readNoFollow(path string, maximum int64) ([]byte, os.FileInfo, error) {
	fd, e := unix.Open(path, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if e != nil {
		return nil, nil, e
	}
	f := os.NewFile(uintptr(fd), path)
	defer f.Close()
	before, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	if !before.Mode().IsRegular() || before.Size() > maximum {
		return nil, nil, fmt.Errorf("%s must be a regular file no larger than %d bytes", path, maximum)
	}
	wire, e := io.ReadAll(io.LimitReader(f, maximum+1))
	if e != nil {
		return nil, nil, e
	}
	after, e := f.Stat()
	if e != nil {
		return nil, nil, e
	}
	named, e := os.Lstat(path)
	if e != nil {
		return nil, nil, e
	}
	if int64(len(wire)) > maximum || !os.SameFile(before, after) || !os.SameFile(before, named) || before.Size() != after.Size() || before.ModTime() != after.ModTime() {
		return nil, nil, fmt.Errorf("%s changed during readback", path)
	}
	return wire, before, nil
}
func LoadJSON(path string, maximum int64) (Object, []byte, error) {
	wire, _, e := readNoFollow(path, maximum)
	if e != nil {
		return nil, nil, e
	}
	var o Object
	e = json.Unmarshal(wire, &o)
	if e != nil {
		return nil, nil, fmt.Errorf("%s invalid JSON: %w", path, e)
	}
	if o == nil {
		return nil, nil, fmt.Errorf("%s must be a JSON object", path)
	}
	return o, wire, nil
}

func pinReason(o Object, p, h, label string, executable bool, reasons *[]string) {
	if e := VerifyPinnedFile(str(o, p), str(o, h), label, executable); e != nil {
		*reasons = append(*reasons, e.Error())
	}
}

func writeMemoryCaptureFiles(t *testing.T, path string) {
	t.Helper()
	if err := os.MkdirAll(path, 0700); err != nil {
		t.Fatal(err)
	}
	for name, raw := range map[string]string{"memory.current": "1\n", "memory.peak": "2\n", "memory.stat": "anon 1\n"} {
		if err := os.WriteFile(filepath.Join(path, name), []byte(raw), 0600); err != nil {
			t.Fatal(err)
		}
	}
}

type Qualifier struct {
	Args                                                    Object
	BakedProfile                                            func() (Object, error)
	CgroupRoot, ProcRoot, ProfilePath, UnitRoot, Executable string
	Command                                                 func(context.Context, []string) (string, error)
	AfterDirectoryOpen                                      func(string)
	ChildVisited                                            func(string)
	Log                                                     []string
}

func (p *Qualifier) roots() {
	if p.CgroupRoot == "" {
		p.CgroupRoot = CgroupRoot
	}
	if p.ProcRoot == "" {
		p.ProcRoot = "/proc"
	}
	if p.ProfilePath == "" {
		p.ProfilePath = "/etc/terrascale-orchestrator/runtime-priority.json"
	}
	if p.UnitRoot == "" {
		p.UnitRoot = "/etc/systemd/system"
	}
	if p.Executable == "" {
		p.Executable, _ = os.Executable()
	}
}

func (p *Qualifier) CaptureMemorySample(cgroups map[string]string, version string) (sample Object, err error) {
	defer recoverError(&err)
	p.roots()
	started := utcNow()
	rows := Object{}
	rootFD, e := unix.Open(p.CgroupRoot, unix.O_RDONLY|unix.O_DIRECTORY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
	if e != nil {
		qfail("cannot anchor cgroup memory sample: %v", e)
	}
	defer unix.Close(rootFD)
	openDirectory := func(path string) (*os.File, error) {
		if !inside(path, p.CgroupRoot) {
			qfail("memory sample escaped cgroup root")
		}
		relative, e := filepath.Rel(p.CgroupRoot, path)
		if e != nil {
			return nil, e
		}
		fd, e := unix.Openat2(rootFD, relative, &unix.OpenHow{Flags: unix.O_RDONLY | unix.O_DIRECTORY | unix.O_CLOEXEC, Resolve: unix.RESOLVE_BENEATH | unix.RESOLVE_NO_SYMLINKS | unix.RESOLVE_NO_MAGICLINKS})
		if e != nil {
			return nil, e
		}
		return os.NewFile(uintptr(fd), path), nil
	}
	sameDirectory := func(path string, meta os.FileInfo) bool {
		named, e := openDirectory(path)
		if e != nil {
			return false
		}
		defer named.Close()
		current, e := named.Stat()
		return e == nil && os.SameFile(meta, current)
	}
	var systemDir *os.File
	var systemMeta os.FileInfo
	for _, scope := range slices.Sorted(maps.Keys(cgroups)) {
		path := cgroups[scope]
		if !inside(path, p.CgroupRoot) {
			qfail("%s memory sample escaped cgroup root", scope)
		}
		dir, e := openDirectory(path)
		if e != nil {
			qfail("cannot capture %s cgroup memory: %v", scope, e)
		}
		defer dir.Close()
		fd := int(dir.Fd())
		func() {
			meta, e := dir.Stat()
			if e != nil {
				qfail("cannot inspect cgroup directory: %v", e)
			}
			if p.AfterDirectoryOpen != nil {
				p.AfterDirectoryOpen(path)
			}
			check := func(stage string) {
				if !sameDirectory(path, meta) {
					qfail("%s memory sample cgroup changed %s capture", scope, stage)
				}
			}
			check("before")
			read := func(name string, max int64) string {
				f, e := unix.Openat(fd, name, unix.O_RDONLY|unix.O_CLOEXEC|unix.O_NOFOLLOW, 0)
				if e != nil {
					qfail("cannot read cgroup %s: %v", name, e)
				}
				file := os.NewFile(uintptr(f), name)
				defer file.Close()
				b, e := io.ReadAll(io.LimitReader(file, max+1))
				if e != nil {
					qfail("cannot read cgroup %s: %v", name, e)
				}
				if int64(len(b)) > max {
					qfail("%s %s exceeds its fixed evidence bound", scope, name)
				}
				return string(b)
			}
			current, peak, stat := read("memory.current", 128), read("memory.peak", 128), read("memory.stat", 16384)
			check("during")
			rows[scope] = Object{"cgroup_path": path, "cgroup_inode": meta.Sys().(*syscall.Stat_t).Ino, "memory_current_raw": current, "memory_current_bytes": integerText(current, "memory.current"), "memory_peak_raw": peak, "memory_peak_bytes": integerText(peak, "memory.peak"), "memory_stat_raw": stat, "memory_stat_sha256": Hash([]byte(stat))}
			if scope == "system_slice" {
				systemDir, systemMeta = dir, meta
			}
		}()
	}
	system := cgroups["system_slice"]
	if systemDir == nil || !sameDirectory(system, systemMeta) {
		qfail("system.slice memory sample cgroup changed before child enumeration")
	}
	children := []string{}
	size := 0
	for {
		entries, e := systemDir.ReadDir(1)
		if e == io.EOF {
			break
		}
		if e != nil {
			qfail("cannot enumerate system.slice: %v", e)
		}
		entry := entries[0]
		if p.ChildVisited != nil {
			p.ChildVisited(entry.Name())
		}
		if entry.Type()&os.ModeSymlink != 0 {
			qfail("system.slice contains symlink while child scopes sampled")
		}
		if !entry.IsDir() {
			continue
		}
		size += len(entry.Name())
		if len(children) >= 256 || size > 16384 {
			qfail("system.slice child-cgroup list exceeds its fixed evidence bound")
		}
		children = append(children, entry.Name())
	}
	if !sameDirectory(system, systemMeta) {
		qfail("system.slice memory sample cgroup changed during child enumeration")
	}
	slices.Sort(children)
	var u unix.Utsname
	if e := unix.Uname(&u); e != nil {
		qfail("cannot read kernel release: %v", e)
	}
	release := string(u.Release[:])
	release, _, _ = strings.Cut(release, "\x00")
	sample = Object{"schema": MemorySampleSchema, "guest_role": str(p.Args, "role"), "host_boot_id": strings.TrimSpace(readText(filepath.Join(p.ProcRoot, "sys/kernel/random/boot_id"), 128)), "kernel_release": release, "systemd_version": version, "started_at_utc": started, "finished_at_utc": utcNow(), "scopes": rows, "system_slice_direct_child_cgroups": children}
	for _, k := range []string{"oci_instance_id", "image_id", "artifact_id", "config_id", "profile_id"} {
		sample[k] = p.Args[k]
	}
	sample["sample_sha256"] = Hash(Canonical(sample))
	return
}
